import pandas as pd
import os

def load_export(path):
    # Use os.path.join for cross-platform compatibility
    full_path = os.path.join(os.path.dirname(__file__), path)

    try:
        return pd.read_csv(full_path, encoding="utf-8", dtype=str, keep_default_na=False)
    except FileNotFoundError as e:
        print(f"Error: {e}")
        return pd.DataFrame()

def parse_dates(df):
    df[['Created Date', 'Close Date']] = pd.to_datetime(
        df[['Created Date', 'Close Date']], 
        errors='coerce'
    )
    return df
